m =10;
k = 1000;
c=10;
u=0;
%%
A=[0 1 ; -k/m -c/m];
B=[0; 1/m];
C = [1 0];
%%
x0 = [-2 0 ];
%%

eig(A) %[output:978973de]
% eigs should 2-5x the eig system

p_o = [-2.4 -2.5] %[output:054ad3d1]
% Place the poles in the desired locations
%%

K_e = place(A', C', p_o);

t_sim = 0:0.01:10;
x0 =[-2 0];
%%

rank(obsv(A,C)) %[output:8b36f437]
%%

function dx = smd(x,A,B,u)
    dx = A*x +B*u;
end
%%

function dx_t = obs(t_o,x_t,A,B,C,u,K_e,y,t)
    y = interp1(t,y,t_o);
    %size(y)
    dx_t = A *x_t + B*u + K_e*(y- C*x_t);
end

%%
[t,x] = ode45(@(t,x)smd(x,A,B,u),t_sim,x0);
size(x) %[output:167660a0]
%%
y = (C*x')';

size(y) %[output:995b497d]
%%
[t_o, x_t] = ode45(@(t_o,x_t)obs(t_o,x_t,A,B,C,u,K_e',y,t),t_sim,x0);

%%
% --- Plot results ---
figure; %[output:61c4fc71]
subplot(2,1,1) %[output:61c4fc71]
plot(t,x(:,1),'b', t_o,x_t(:,1),'r--'); %[output:61c4fc71]
legend('True state x1','Estimated x1'); %[output:61c4fc71]
xlabel('Time (s)'); ylabel('Displacement'); %[output:61c4fc71]

subplot(2,1,2) %[output:61c4fc71]
plot(t,x(:,2),'b', t_o,x_t(:,2),'r--'); %[output:61c4fc71]
legend('True state x2','Estimated x2'); %[output:61c4fc71]
xlabel('Time (s)'); ylabel('Velocity'); %[output:61c4fc71]

